// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFileName 是每仓库低库存阈值的配置文件名。它位于本 package 目录下，
// 从仓库根看就是 inventory/thresholds.json，内容形如 {"shanghai": 20}。
const thresholdsFileName = "thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值优先取自 inventory/thresholds.json；该文件不存在、无法解析，
// 或里面没有这个仓库时，回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

// loadThresholds 读取每仓库的阈值配置。读取或解析失败时返回 nil，
// 于是所有仓库都回退到默认值。这里刻意不缓存：配置文件被替换后应当立即生效，
// 测试也可以先写文件再断言。
func loadThresholds() map[string]int {
	path, ok := findThresholdsFile()
	if !ok {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var configured map[string]int
	if err := json.Unmarshal(data, &configured); err != nil {
		return nil
	}
	return configured
}

// findThresholdsFile 返回第一个存在的配置文件位置。进程的工作目录可能是
// 仓库根，也可能是 package 目录（go test 就以 package 目录为工作目录），
// 所以先按源码位置定位，再退回两个工作目录相对路径。
func findThresholdsFile() (string, bool) {
	candidates := make([]string, 0, 3)
	if _, file, _, ok := runtime.Caller(0); ok {
		candidates = append(candidates, filepath.Join(filepath.Dir(file), thresholdsFileName))
	}
	candidates = append(candidates,
		filepath.Join("inventory", thresholdsFileName), // 工作目录是仓库根
		thresholdsFileName,                            // 工作目录是 package 目录
	)
	for _, path := range candidates {
		if _, err := os.Stat(path); err == nil {
			return path, true
		}
	}
	return "", false
}

package inventory

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

// configuredThresholdsFile 返回配置文件的规范位置（package 目录下），
// 与 findThresholdsFile 的首选位置一致。
func configuredThresholdsFile(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("无法定位测试文件")
	}
	return filepath.Join(filepath.Dir(file), thresholdsFileName)
}

// withThresholdsFile 写入配置内容，并在测试结束后恢复原状。
func withThresholdsFile(t *testing.T, content string) {
	t.Helper()
	path := configuredThresholdsFile(t)
	original, err := os.ReadFile(path)
	hadOriginal := err == nil
	t.Cleanup(func() {
		if hadOriginal {
			_ = os.WriteFile(path, original, 0o644)
		} else {
			_ = os.Remove(path)
		}
	})
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("写入 %s: %v", path, err)
	}
}

func TestConfiguredWarehouseUsesOwnThreshold(t *testing.T) {
	withThresholdsFile(t, `{"shanghai": 20}`)

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望 20", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
	if !IsLowStock("shanghai", 19) {
		t.Fatal("低于该仓库阈值应当算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("等于该仓库阈值不算低库存（严格小于）")
	}
}

func TestMalformedThresholdsFallBackToDefault(t *testing.T) {
	withThresholdsFile(t, `{not json`)

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("配置无法解析时应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

